mapper.select:
SELECT A.SEQNO SEQNO, A.CREDIT_MST_ID creditMstId, A.CUSTOMER_ID customerId, A.TERM TERM, A.PFLSH PFLSH, A.PFLSH_NAME pflshName, A.CREDIT_AMT/100000000 creditAmt, A.VDATE VDATE, A.MDATE MDATE, A.REMARK, A.HAP_CREDIT_AMT as hapCreditAmt, A.CREDIT_FLAG as creditFlag, C.FINPROD_NAME as customerName
,A.INSTITUTION_CODE as institutionCode
FROM CREDIT_LINES A INNER JOIN CREDIT_MST_INFO B on A.CREDIT_MST_ID=B.SEQNO and B.CREDIT_INFO_TYPE in ('02') left join FIN_PRODUCT C on A.CUSTOMER_ID=C.FINPROD_ID
A.CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}
AND A.PFLSH LIKE CONCAT(CONCAT('%',#{pflsh}),'%')
AND A.PFLSH_NAME LIKE CONCAT(CONCAT('%',#{pflshName}),'%')
AND to_char(A.VDATE,'yyyy-MM-dd') > = #{vdate,jdbcType=DATE}
AND to_char(A.VDATE,'yyyy-MM-dd') < = #{mdate,jdbcType=DATE}
